         body='ONE. (continued)\n  THE MODEL (Python written by the program: 66 lines):\n    tm = TM("Bank payments")\n    dmz = Boundary("DMZ")\n    gateway = Server("API gateway")\n    gateway.inBoundary = dmz\n    f2 = Dataflow(app, gateway, "Payment request with token")\n    f2.protocol = "HTTPS"\n    tm.process()',
